<?php
require_once __DIR__.'/../../config/db.php'; require_once __DIR__.'/../../config/security.php'; requireRole('HR Administrator');
$pageTitle='Data Import'; $message='';
if($_SERVER['REQUEST_METHOD']==='POST'){ verify_csrf(); $type=$_POST['type']??''; if($type==='employees' && isset($_FILES['csv']) && is_uploaded_file($_FILES['csv']['tmp_name'])){ $fh=fopen($_FILES['csv']['tmp_name'],'r'); $header=fgetcsv($fh); $required=['employee_id','first_name','last_name','gender','date_of_birth','email','date_hired']; if(!$header || array_diff($required,$header)){ $message='Invalid CSV columns. Required: '.implode(', ',$required); } else { $pdo->beginTransaction(); try{$idx=array_flip($header); $q=$pdo->prepare("INSERT INTO employees(employee_id,first_name,middle_name,last_name,gender,date_of_birth,address,contact_number,email,department_id,position_id,employment_status,date_hired,basic_salary) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)"); $n=0; while(($r=fgetcsv($fh))!==false){$get=fn($k)=>$r[$idx[$k]]??null; $q->execute([$get('employee_id'),$get('first_name'),$get('middle_name'),$get('last_name'),$get('gender'),$get('date_of_birth'),$get('address'),$get('contact_number'),$get('email'),$get('department_id')?:null,$get('position_id')?:null,$get('employment_status')?:'Probationary',$get('date_hired'),(float)($get('basic_salary')?:0)]);$n++;} $pdo->commit(); audit($pdo,'IMPORT','employees',null,"Imported $n employee rows"); $message="Imported $n employee record(s).";}catch(Throwable $e){$pdo->rollBack();$message='Import failed: '.$e->getMessage();}} fclose($fh);} else {$message='Choose Employees and upload a CSV file.';}}
include __DIR__.'/../../includes/header.php';
?>
<div class="card"><h2>Employee CSV Import</h2><p>Manually import employee records using the required columns shown below. Integration files are received through the API and generate notifications only when a file arrives. Invalid files are rejected before database changes are committed.</p><div class="code-note">employee_id, first_name, middle_name, last_name, gender, date_of_birth, address, contact_number, email, department_id, position_id, employment_status, date_hired, basic_salary</div><?php if($message): ?><div class="alert alert-info"><?= htmlspecialchars($message) ?></div><?php endif; ?><form method="post" enctype="multipart/form-data" class="stack-form"><?= csrf_field() ?><input type="hidden" name="type" value="employees"><label>CSV file<input type="file" name="csv" accept=".csv,text/csv" required></label><button class="btn btn-primary">Import Employees</button></form></div>
